<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useB1Store } from '../stores/b1'
const b1 = useB1Store(); const router = useRouter(); const context = computed(() => b1.continueContext); const elapsed = ref(0); let timer: number | undefined
onMounted(() => { b1.restore(); void b1.loadContinueContext(); timer = window.setInterval(() => { elapsed.value += 1 }, 1000) }); onUnmounted(() => { if (timer) window.clearInterval(timer) })
function saveAndExit(): void { void b1.updateContinueContext({ elapsedTimeMs: (context.value?.elapsedTimeMs ?? 0) + elapsed.value * 1000 }); router.push({ name: 'today' }) }
function complete(): void { b1.completeContinue(); router.push({ name: 'today' }) }
</script>
<template><section class="page-stack" aria-labelledby="learn-title"><article class="lesson-card"><p class="eyebrow">{{ context?.moduleLabel ?? '核心学习' }}</p><h2 id="learn-title">{{ context?.lessonTitle ?? '开始一节 3 分钟学习' }}</h2><p class="lead">本节围绕一个真实场景，先理解表达，再完成一次主动回忆。</p><div class="lesson-progress"><span :style="{ width: `${Math.round(((context?.stepIndex ?? 1) / (context?.totalSteps ?? 5)) * 100)}%` }"></span></div><div class="lesson-meta"><span>步骤 {{ context?.stepIndex ?? 1 }}/{{ context?.totalSteps ?? 5 }}</span><span>本次 {{ elapsed }} 秒</span></div></article><article class="info-card"><span class="card-kicker">本步提示</span><h3>先大声读出这句话</h3><p>Could you show me where the check-in counter is? 先抓住请求方向，再注意礼貌语气。</p><div class="actions"><button class="button button--secondary" type="button" @click="saveAndExit">保存断点</button><button class="button button--primary" type="button" @click="complete">完成本步</button></div></article></section></template>
